"""
最大クリーク・最大独立集合・最小点被覆 (Maximum Clique & Independent Set)
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
- max_clique(n, g): 最大クリーク (互いに隣接する最大頂点集合) を求める。
  Bron-Kerbosch法 (ピボット選択付き) により高速動作 (N <= 40 程度に対応)。
- max_independent_set(n, g): 最大独立集合 (どの2頂点も隣接しない最大集合)。
  補グラフにおける最大クリークと同値。
- min_vertex_cover(n, g): 最小点被覆 (全辺の少なくとも一方の端点を含む最小集合)。
  全頂点集合 - 最大独立集合。

【引数】
- n: 頂点数 (0 ~ n-1)
- g: 隣接セットリスト [{v1, v2, ...}, ...] (無向グラフ)
"""

# https://github.com/ddfkit/acsampl/blob/main/graphth.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def max_clique(n,g):
    def bk(r,p,x):
        if not p and not x:return r
        u=next(iter(p|x));best=set()
        for v in list(p-g[u]):
            res=bk(r|{v},p&g[v],x&g[v])
            if len(res)>len(best):best=res
            p.remove(v);x.add(v)
        return best
    deg=sorted(range(n),key=lambda x:len(g[x]),reverse=True)
    ans,p,x=set(),set(range(n)),set()
    for v in deg:
        res=bk({v},p&g[v],x&g[v])
        if len(res)>len(ans):ans=res
        p.remove(v);x.add(v)
    return ans

# https://github.com/ddfkit/acsampl/blob/main/graphth.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def max_independent_set(n,g):
    cg=[set(range(n))-{i}-g[i] for i in range(n)]
    return max_clique(n,cg)

# https://github.com/ddfkit/acsampl/blob/main/graphth.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def min_vertex_cover(n,g):
    return set(range(n))-max_independent_set(n,g)

if __name__ == "__main__":
    g = [{1, 2, 3}, {0, 2}, {0, 1}, {0}]
    clq = max_clique(4, g)
    assert clq == {0, 1, 2}
    mis = max_independent_set(4, g)
    assert len(mis) == 2
    mvc = min_vertex_cover(4, g)
    assert len(mvc) == 2
    print("graphth.py: tests passed!")
